using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.CostCenters.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;using Namaa.Domain.Entities;namespace Namaa.Application.CostCenters.Commands.CreateCostCenter;public sealed class CreateCostCenterCommandHandler(ICostCenterRepository repository,IApplicationDbContext db):IRequestHandler<CreateCostCenterCommand,Result<CostCenterDto>>{public async Task<Result<CostCenterDto>>Handle(CreateCostCenterCommand request,CancellationToken cancellationToken){if(await repository.ExistsByCostCenterCodeAsync(request.CostCenterCode,cancellationToken))return Result.Failure<CostCenterDto>(CostCenterErrors.Duplicate);var e=CostCenter.Create(request.CostCenterCode,request.Name,request.Description,request.ParentCostCenterId,request.BranchId);await repository.AddAsync(e,cancellationToken);await db.SaveChangesAsync(cancellationToken);return Result.Success(CostCenterDto.FromEntity(e));}}
